const waitFor=async(predicate,message)=>{for(let i=0;i<120;i++){const s=await state();if(predicate(s)){await pause(120);return s;}await pause(50);}throw Error(message);};
const findControl=(s,key)=>{for(const prefix of ['morph','scene','layer','transform'])if(s[prefix+'_controls']?.[key])return {rect:s[prefix+'_controls'][key],enabled:s[prefix+'_controls_enabled']?.[key],prefix};return null;};
async function control(key,allowDisabled=false){for(let i=0;i<20;i++){const s=await state(),c=findControl(s,key);assert(c,'Missing actual rendered control: '+key);const r=c.rect,p=[(r[0]+r[2])/2,(r[1]+r[3])/2];if(p[1]>72&&p[1]<945&&r[0]>=0&&r[2]<=1600){assert(allowDisabled||c.enabled!==false,'Unexpected disabled control: '+key);return {...c,point:p};}const delta=p[1]>945?350:-350;result.ui_actions.push({key:'scroll-for.'+key,before:r,delta_y:delta});await wheel([p[0],740],delta);const next=findControl(await state(),key);assert(next&&(delta>0?next.rect[1]<r[1]:next.rect[1]>r[1]),'Normal panel scroll did not expose '+key);}throw Error('Control remains outside viewport: '+key);}
async function action(key,allowDisabled=false){const c=await control(key,allowDisabled);result.ui_actions.push({key,...c,at_epoch_ms:Date.now()});await click(c.point);return state();}
async function enable(key,field,value){if((await state())[field]!==value)await action(key);return waitFor(s=>s[field]===value,'Actual checkbox did not set '+field);}
async function sliderEndpoint(key,field,value){const c=await control(key);await click([value===0?c.rect[0]+1:c.rect[2]-1,c.point[1]]);return waitFor(s=>Math.fround(s[field])===Math.fround(value),'Actual slider endpoint differs '+field);}
async function numeric(controlKey,value,read){const c=await control(controlKey);await pointer('mouseMoved',...c.point);for(const count of [1,2]){await pointer('mousePressed',...c.point,true,'left',0,count);await pause(25);await pointer('mouseReleased',...c.point,false,'left',0,count);await pause(50);}await chord('a');await send('Input.insertText',{text:String(value)});await key('Enter');await pause(180);result.ui_actions.push({key:controlKey,value,point:c.point});return waitFor(s=>Math.fround(read(s))===Math.fround(value),'Actual numeric control differs '+controlKey);}
async function chooseCombo(parent,item,predicate){await action(parent);await action(item);return waitFor(predicate,'Actual combo did not select '+item);}
async function gpu(){const g=await evaluate('window.__readSceneGpu()');g.sha256=hash(JSON.stringify(g.draws.map(d=>[d.active,d.vertex_sha256,d.index_sha256,d.count,d.material_sha256,d.material_bytes,d.material_enabled,d.has_material_data,d.default_material]).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)))));return g;}
function packedVertex(mesh){const bytes=Buffer.alloc(mesh.positions.length*40);mesh.positions.forEach((p,i)=>[...p,...mesh.normals[i],mesh.masks[i],...mesh.colors[i]].forEach((v,c)=>bytes.writeFloatLE(v,i*40+c*4)));return hash(bytes);}
function packedIndices(mesh){const bytes=Buffer.alloc(mesh.triangles.length*12);mesh.triangles.forEach((t,i)=>t.forEach((v,c)=>bytes.writeUInt32LE(v,i*12+c*4)));return hash(bytes);}
function packedMaterials(mesh){const rows=mesh.materials||[],bytes=Buffer.alloc(rows.length*8);rows.forEach((row,i)=>row.forEach((v,c)=>bytes.writeFloatLE(v,i*8+c*4)));return hash(bytes);}
const objectStates=document=>document.scene?document.scene.objects.map(o=>({...o,state:o.id===document.scene.active_id?{mesh:document.mesh,multiresolution:document.multiresolution,layers:document.layers,morph_target:document.morph_target}:o.payload})): [{id:1,name:document.name,visible:true,state:{mesh:document.mesh,multiresolution:document.multiresolution,layers:document.layers,morph_target:document.morph_target}}];
function matchGpu(document,actual){const active=document.scene?.active_id??1,solo=document.scene?.solo??false,visible=objectStates(document).filter(o=>o.visible&&(!solo||o.id===active));const expected=visible.map(o=>JSON.stringify([o.id===active,packedVertex(o.state.mesh),packedIndices(o.state.mesh),o.state.mesh.triangles.length*3,o.state.mesh.positions.length*40,o.state.mesh.triangles.length*12,packedMaterials(o.state.mesh),(o.state.mesh.materials?.length||0)*8,!!o.state.mesh.materials,!!o.state.mesh.materials])).sort(),observed=actual.draws.map(d=>JSON.stringify([d.active,d.vertex_sha256,d.index_sha256,d.count,d.vertex_bytes,d.index_bytes,d.material_sha256,d.material_bytes,d.has_material_data,d.material_enabled])).sort();assert(actual.draws.every(d=>d.type===5125&&d.offset===0),'Unexpected rendered solid index format');assert(actual.draws.every(d=>floatChannelsEqual(d.default_material,[Math.fround(.18),Math.fround(.08)])),'Default roughness/metallic uniform differs');return JSON.stringify(expected)===JSON.stringify(observed);}
async function download(stage,trigger,extension){const at=downloadEvents.length;await trigger();let entry;for(let i=0;i<120;i++){entry=downloadEvents.slice(at).find(e=>e.state==='completed');if(entry)break;await pause(80);}assert(entry,'Actual browser download did not complete: '+stage);const original=path.join(downloads,entry.guid),bytes=await readFile(original);assert(bytes.length>0&&bytes.length<=128*1024*1024,'Download outside 128 MiB cap');assert(path.extname(entry.suggestedFilename)==='.'+extension,'Actual download extension mismatch');const file=path.join(out,stage+'.'+extension);await rename(original,file);const record={name:entry.suggestedFilename,path:file,bytes:bytes.length,sha256:hash(bytes),guid:entry.guid,completed_event:{...entry}};result.downloads.push(record);return {record,bytes};}
async function snapshot(stage){const {record,bytes}=await download(stage,()=>chord('s'),'obrush'),document=JSON.parse(bytes.toString('utf8'));await pause(100);const actual=await gpu(),metrics=await state(),matches=matchGpu(document,actual);const item={...record,gpu:actual,metrics,gpu_matches_saved_scene:matches,vertices:document.mesh.positions.length,triangles:document.mesh.triangles.length};result.snapshots.push(item);result.gpu_checks.push({stage,gpu:actual,match:matches});assert(matches,'Actual visible GPU vertex/index channels differ from project: '+stage);return {record:item,document};}
async function screenshot(stage){const r=await send('Page.captureScreenshot',{format:'png',fromSurface:true});const bytes=Buffer.from(r.data,'base64'),file=path.join(out,stage+'.png');await writeFile(file,bytes);const receipt={path:file,bytes:bytes.length,sha256:hash(bytes)};result.screenshots.push(receipt);return receipt;}
async function diagnostics(stage){const d=await evaluate('({gpu:window.__brushCheck,files:window.__hostFiles,notice:document.getElementById("notice")?.textContent})');const g=d.gpu;const clean={stage,gl_errors:g.gl_errors,js_errors:g.js_errors,contexts:g.contexts,allocations:g.allocations,events:g.events,keys:g.keys,wheels:g.wheels,files:d.files,notice:d.notice};result.page_diagnostics.push(clean);assert(!g.gl_errors.length&&!g.js_errors.length,'Page runtime error: '+stage);assert(g.events.every(e=>e.trusted)&&g.keys.every(e=>e.trusted)&&d.files.events.every(e=>e.trusted),'Untrusted actual input/file event');return clean;}
async function fresh(){if(await evaluate('!!window.__brushCheck'))await diagnostics('before-navigation');await send('Page.navigate',{url:result.url});for(let i=0;i<150;i++){if(await evaluate('!document.getElementById("loading")&&typeof window.obrushBrushMetrics==="function"&&window.__brushMeshVbo&&window.__readSceneGpu')){await pause(250);return state();}await pause(100);}throw Error('Frozen OBrush startup timeout');}
async function importFile(fixture,append=false,rejection=false){const before=await state(),noticeAt=await evaluate('window.__hostFiles.notice_events.length');if(append)await action('scene.append_obj');else await chord('o');const root=(await send('DOM.getDocument')).root,node=(await send('DOM.querySelector',{nodeId:root.nodeId,selector:'#import-file'})).nodeId;assert(node,'Normal import input missing');await send('DOM.setFileInputFiles',{nodeId:node,files:[fixture.path]});for(let i=0;i<120;i++){const s=await state(),notice=await evaluate('document.getElementById("notice").textContent');if(rejection&&notice&&(await evaluate('window.__hostFiles.notice_events.length'))>noticeAt){await pause(150);return {metrics:s,notice,notice_observations:await evaluate('window.__hostFiles.notice_events.slice('+noticeAt+')')};}if(!rejection&&notice)throw Error(notice);if(!rejection&&(append?s.subtools.length===before.subtools.length+1:s.vertices===fixture.expected.vertices)&&s.message.startsWith(append?'Appended ':'Loaded ')){await pause(180);return {metrics:s};}await pause(60);}throw Error('Normal file import/rejection timed out: '+fixture.path);}
async function loadBrushFixture(){await fresh();await importFile(sphere);const s=await state();assert(Math.fround(s.radius)===Math.fround(.18)&&Math.fround(s.strength)===Math.fround(.35)&&s.symmetry_x,'Actual default brush parameters differ');return s;}
async function backgroundFocus(){const s=await state(),r=s.camera.viewport;await click([r[2]-25,r[3]-25]);}
const brushes=[['Draw','1'],['Clay','2'],['Inflate','3'],['Smooth','4'],['Flatten','5'],['Crease','6'],['Move','7'],['Mask','8'],['Paint','9'],['Morph','0'],['Pinch','p'],['Twist','j'],['Local Scale','l'],['Drag','g']];
async function selectBrush(name){await backgroundFocus();await key(brushes.find(b=>b[0]===name)[1]);return waitFor(s=>s.kind===name,'Normal brush shortcut did not select '+name);}
function difference(a,b,field='positions'){const x=a[field],y=b[field];assert(y.length>=x.length,'Original vertex domain disappeared');let count=0,max=0,squared=0;for(let i=0;i<x.length;i++){const old=Array.isArray(x[i])?x[i]:[x[i]],now=Array.isArray(y[i])?y[i]:[y[i]];let sq=0;for(let c=0;c<old.length;c++){const d=Math.fround(now[c])-Math.fround(old[c]);sq+=d*d;}count+=Number(sq>0);max=Math.max(max,Math.sqrt(sq));squared+=sq;}return {changed:count,original_count:x.length,after_count:y.length,max,rms:Math.sqrt(squared/x.length)};}
function protectedPositions(a,b){return a.masks.every((v,i)=>Math.fround(v)!==1||a.positions[i].every((x,c)=>Object.is(Math.fround(x),Math.fround(b.positions[i][c]))));}
async function contact(mesh){const s=await state(),m=s.camera.view_projection,r=s.camera.viewport,eye=s.camera.position,normal=eye.map((x,i)=>x-s.camera.target[i]);const best=mesh.positions.reduce((winner,p)=>p.reduce((sum,x,i)=>sum+x*normal[i],0)>winner.reduce((sum,x,i)=>sum+x*normal[i],0)?p:winner);const clip=[0,1,2,3].map(i=>m[i]*best[0]+m[i+4]*best[1]+m[i+8]*best[2]+m[i+12]);assert(clip[3]>0,'Contact behind actual camera');return {point:best,screen:[r[0]+(r[2]-r[0])*(clip[0]/clip[3]+1)/2,r[1]+(r[3]-r[1])*(1-clip[1]/clip[3])/2].map(Math.round),camera:s.camera};}
async function quiet(stage){const probes=[];for(const delay of [0,200,800]){await pause(delay);const actual=await gpu(),sculpt=await evaluate('window.obrushSculptMetrics()');probes.push({at_epoch_ms:Date.now(),gpu:actual,sculpt});}const pass=probes.every(p=>p.gpu.sha256===probes[0].gpu.sha256&&p.sculpt.pending_dabs===0);assert(pass,'Geometry or pending dabs changed after release: '+stage);return {probes,pass};}
async function stroke(name,mesh,options={}){const c=options.ray?await rayContact(mesh):await contact(mesh),center=c.screen,kind=(await state()).kind;let points;
  if(kind==='Twist')points=[[0,0],[32,0],[28,16],[16,28],[0,32],[-16,28],[-28,16],[-32,0]].map(p=>p.map((x,i)=>center[i]+x));
  else if(kind==='Local Scale')points=Array.from({length:9},(_,i)=>[center[0]+i*6,center[1]]);
  else if(options.fast)points=Array.from({length:81},(_,i)=>[center[0]+50*Math.sin(i*.15),center[1]+25*Math.cos(i*.15)]);
  else points=Array.from({length:9},(_,i)=>[center[0]+i*4,center[1]+3*Math.sin(i*.5)]);
  await pointer('mouseMoved',...points[0]);await pause(40);await pointer('mousePressed',...points[0],true);for(const p of points.slice(1)){await pointer('mouseMoved',...p,true);if(!options.fast)await pause(30);}await pointer('mouseReleased',...points.at(-1));const tail=await quiet(name),trial={name,kind,contact:c,input_points:points,spacing_ms:options.fast?0:30,tail};result.strokes.push(trial);return trial;
}
async function history(name,before,after){await chord('z');const undo=await snapshot(name+'-undo');await chord('z',true);const redo=await snapshot(name+'-redo');const checks={undo_exact:undo.record.sha256===before.record.sha256,redo_exact:redo.record.sha256===after.record.sha256};assert(Object.values(checks).every(Boolean),'Whole downloaded project history differs: '+name);return checks;}
