async function brushCases(){
  for(const [name] of brushes){
    await loadBrushFixture();
    if(name==='Morph'){await action('morph.store');await selectBrush('Draw');const prep=await snapshot('morph-preparation-base');await stroke('morph-preparation-draw',prep.document.mesh);}
    await selectBrush(name);const stem='brush-'+name.toLowerCase().replaceAll(' ','-'),before=await snapshot(stem+'-before'),settings=await state(),gesture=await stroke(stem,before.document.mesh,{fast:name==='Drag'}),after=await snapshot(stem+'-after');
    const field=name==='Mask'?'masks':name==='Paint'?'colors':'positions',change=difference(before.document.mesh,after.document.mesh,field),protection=protectedPositions(before.document.mesh,after.document.mesh);
    assert(change.changed>0,'Brush made no useful '+field+' edit: '+name);assert(protection,'Brush moved fully masked points: '+name);
    const undoRedo=await history(stem,before,after);await finishCase({name:stem,scope:'Local brush workflow; reference parity unverified',tool:name,settings,before:before.record,after:after.record,gesture,change,history:undoRedo,gates:{normal_shortcut:settings.kind===name,useful_channel_edit:change.changed>0,fully_masked_positions_exact:protection,visible_gpu_save_exact:true,undo_exact:undoRedo.undo_exact,redo_exact:undoRedo.redo_exact,release_quiet:gesture.tail.pass}});
  }
}
