  const states=[];states.push(await enable('settings.screen_space','screen_space_radius',true));assert(Math.fround(states.at(-1).screen_radius_pixels)===75,'Default screen radius differs');states.push(await sliderEndpoint('settings.hardness','hardness',1));states.push(await enable('settings.culling','backface_culling',true));states.push(await numeric('settings.symmetry_offset',.125,s=>s.symmetry_offset));states.push(await enable('settings.draw_clay','draw_clay',true));states.push(await enable('settings.draw_accumulate','draw_accumulate',false));
